#include <stddef.h>
extern void terminal_key(char c); extern void terminal_draw(void); extern void menu_draw(void);
static unsigned char *fb; static unsigned pitch; static int W=1024,H=768;
static unsigned rgb(unsigned char r,unsigned char g,unsigned char b){return r|(g<<8)|(b<<16);}
void pixel(int x,int y,unsigned c){if(x>=0&&x<W&&y>=0&&y<H)*(unsigned*)(fb+y*pitch+x*4)=c;}
void rect(int x,int y,int w,int h,unsigned c){for(int j=0;j<h;j++)for(int i=0;i<w;i++)pixel(x+i,y+j,c);}
static const unsigned char *glyph(char c){static unsigned char z[7]; z[0]=z[1]=z[2]=z[3]=z[4]=z[5]=z[6]=0; 
#define G(a,b,c,d,e,f,g) do{z[0]=a;z[1]=b;z[2]=c;z[3]=d;z[4]=e;z[5]=f;z[6]=g;}while(0)
if(c>='a'&&c<='z')c-=32; switch(c){case 'A':G(14,17,17,31,17,17,17);break;case 'B':G(30,17,17,30,17,17,30);break;case 'C':G(15,16,16,16,16,16,15);break;case 'D':G(30,17,17,17,17,17,30);break;case 'E':G(31,16,16,30,16,16,31);break;case 'F':G(31,16,16,30,16,16,16);break;case 'G':G(15,16,16,23,17,17,15);break;case 'H':G(17,17,17,31,17,17,17);break;case 'I':G(31,4,4,4,4,4,31);break;case 'J':G(7,2,2,2,18,18,12);break;case 'K':G(17,18,20,24,20,18,17);break;case 'L':G(16,16,16,16,16,16,31);break;case 'M':G(17,27,21,21,17,17,17);break;case 'N':G(17,25,21,19,17,17,17);break;case 'O':G(14,17,17,17,17,17,14);break;case 'P':G(30,17,17,30,16,16,16);break;case 'Q':G(14,17,17,17,21,18,13);break;case 'R':G(30,17,17,30,20,18,17);break;case 'S':G(15,16,16,14,1,1,30);break;case 'T':G(31,4,4,4,4,4,4);break;case 'U':G(17,17,17,17,17,17,14);break;case 'V':G(17,17,17,17,17,10,4);break;case 'W':G(17,17,17,21,21,21,10);break;case 'X':G(17,17,10,4,10,17,17);break;case 'Y':G(17,17,10,4,4,4,4);break;case 'Z':G(31,1,2,4,8,16,31);break;case '0':G(14,17,19,21,25,17,14);break;case '1':G(4,12,4,4,4,4,14);break;case '2':G(14,17,1,2,4,8,31);break;case '3':G(30,1,1,14,1,1,30);break;case '4':G(2,6,10,18,31,2,2);break;case '5':G(31,16,16,30,1,1,30);break;case '6':G(14,16,16,30,17,17,14);break;case '7':G(31,1,2,4,8,8,8);break;case '8':G(14,17,17,14,17,17,14);break;case '9':G(14,17,17,15,1,1,14);break;case ':':G(0,4,4,0,4,4,0);break;case '.':G(0,0,0,0,0,6,6);break;case '-':G(0,0,0,31,0,0,0);break;case '/':G(1,2,2,4,8,8,16);break;case '_':G(0,0,0,0,0,0,31);break;case '>':G(16,8,4,2,4,8,16);break;case '!':G(4,4,4,4,4,0,4);break;case '?':G(14,17,1,2,4,0,4);break;case '(':G(2,4,8,8,8,4,2);break;case ')':G(8,4,2,2,2,4,8);break;case ' ':break; default:G(31,17,21,17,21,17,31);} return z;}
void text(int x,int y,const char*s,unsigned col){while(*s){const unsigned char*g=glyph(*s++);for(int j=0;j<7;j++)for(int i=0;i<5;i++)if(g[j]&(1<<(4-i)))rect(x+i*2,y+j*2,2,2,col);x+=12;}}
void gui_init(unsigned addr,unsigned p,int w,int h){fb=(unsigned char*)addr;pitch=p;W=w;H=h;rect(0,0,W,H,rgb(25,31,42));rect(0,0,W,36,rgb(25,53,78));text(18,12,"xOS",rgb(220,235,245));text(90,12,"APPLICATIONS",rgb(180,205,220));text(W-150,12,"LITE  00:00",rgb(200,220,230));rect(40,95,210,130,rgb(38,49,63));text(60,115,"FILES",rgb(225,235,240));text(60,150,"README.TXT",rgb(170,195,210));text(60,175,"ABOUT.TXT",rgb(170,195,210));rect(40,255,210,245,rgb(32,43,56));text(58,275,"APPLICATION MENU",rgb(210,225,235));text(58,305,"TERMINAL",rgb(170,195,210));text(58,330,"SETTINGS",rgb(170,195,210));text(58,355,"SYSTEM INFO",rgb(170,195,210));text(58,380,"ABOUT",rgb(170,195,210));text(58,420,"REBOOT",rgb(200,175,165));text(58,445,"SHUTDOWN",rgb(200,175,165));rect(290,95,590,430,rgb(31,40,52));rect(290,95,590,28,rgb(46,72,93));text(308,105,"TERMINAL",rgb(225,235,240));text(310,145,"xOS v1 Lite terminal",rgb(175,220,190));text(310,170,"Type help for available commands.",rgb(175,220,190));terminal_draw();}
void gui_present(void){ }
void gui_input(char c){terminal_key(c);}
